// --- helpers ---

func scaleIngredientView(ing store.IngredientRow, factor float64) ingredientView {
	quantity := ing.Quantity
	scaledQuantity := quantity
	if value, unit, ok := parseQuantityPrefix(quantity); ok {
		scaledQuantity = strings.TrimSpace(formatQuantity(value*factor) + " " + unit)
	}
	formContext := ""
	if ing.RawIngredient != "" {
		formContext = "raw"
	} else if quantity != "" && ing.Name != "" {
		formContext = "parsed"
	} else {
		formContext = "unparsed"
	}
	return ingredientView{
		Name:           ing.Name,
		Quantity:       quantity,
		ScaledQuantity: scaledQuantity,
		Note:           ing.Note,
		RawIngredient:  ing.RawIngredient,
		FormContext:    formContext,
	}
}

func recipeScaleFactor(servings string, target int) float64 {
	if target <= 0 {
		return 0
	}
	original := parseLeadingInt(servings)
	if original <= 0 {
		return 0
	}
	return float64(target) / float64(original)
}

func freshReadCandidates(ctx context.Context, cfg *config.Config, st *store.Store, listName string) ([]candidateView, pricingSummaryView, error) {
	// Resolve local list first.
	if _, err := st.FindListByName(listName); err != nil {
		return nil, pricingSummaryView{}, fmt.Errorf("list %q not found — run 'anylist-pp-cli sync' first: %w", listName, err)
	}

	// Fresh-read from API via GetUserData (which includes shopping lists).
	alClient := anylist.New(cfg)
	userData, err := alClient.GetUserData(ctx)
	if err != nil {
		return nil, pricingSummaryView{}, fmt.Errorf("fresh reading list %q: %w", listName, err)
	}

	// Find the target list in the live response.
	slResp := userData.GetShoppingListsResponse()
	if slResp == nil {
		return nil, pricingSummaryView{}, fmt.Errorf("no shopping-list data returned from API")
	}

	var targetItems []*pb.ListItem
	var targetListFound bool
	for _, l := range slResp.GetNewLists() {
		if l.GetName() == listName {
			targetListFound = true
			for _, item := range l.GetItems() {
				targetItems = append(targetItems, item)
			}
		}
	}
	for _, l := range slResp.GetModifiedLists() {
		if l.GetName() == listName {
			targetListFound = true
			for _, item := range l.GetItems() {
				targetItems = append(targetItems, item)
			}
		}
	}
	if !targetListFound {
		return nil, pricingSummaryView{}, fmt.Errorf("list %q not found in fresh API response", listName)
	}

	// Collect all stores for name lookup.
	storeMap := make(map[string]string)
	for _, lr := range slResp.GetListResponses() {
		for _, store := range lr.GetStores() {
			storeMap[store.GetIdentifier()] = store.GetName()
		}
	}

	// Serialize candidates.
	candidates := make([]candidateView, 0, len(targetItems))
	availablePrices := make([]priceInfoView, 0)
	missingCount := 0

	for _, item := range targetItems {
		c := candidateView{
			ID:              item.GetIdentifier(),
			Name:            item.GetName(),
			Quantity:        item.GetQuantity(),
			Details:         item.GetDetails(),
			Checked:         item.GetChecked(),
			Category:        item.GetCategory(),
			CategoryMatchID: item.GetCategoryMatchId(),
			Barcode:         item.GetProductUpc(),
			PhotoIDs:        item.GetPhotoIds(),
			PackageSize:     item.GetPackageSizePb().GetRawPackageSize(),
		}
		// Collect store IDs.
		for _, sid := range item.GetStoreIds() {
			c.StoreIDs = append(c.StoreIDs, sid)
		}
		candidates = append(candidates, c)

		// Collect prices.
		for _, p := range item.GetPrices() {
			amount := p.GetAmount()
			storeID := p.GetStoreId()
			storeName := storeMap[storeID]
			if storeName == "" {
				storeName = storeID // fallback to ID
			}
			availablePrices = append(availablePrices, priceInfoView{
				ItemName:  item.GetName(),
				Amount:    amount,
				StoreName: storeName,
			})
		}
		if len(item.GetPrices()) == 0 {
			missingCount++
		}
	}

	// Calculate total of available prices.
	var totalPrices float64
	for _, p := range availablePrices {
		totalPrices += p.Amount
	}

	return candidates, pricingSummaryView{
		TotalAvailablePrices: totalPrices,
		MissingPriceCount:    missingCount,
		AvailablePrices:      availablePrices,
	}, nil
}

// stringArrayFromBody extracts a []string from a JSON map for a given key.
func stringArrayFromBody(body map[string]any, key string) []string {
	v, ok := body[key]
	if !ok {
		return nil
	}
	switch arr := v.(type) {
	case []string:
		return arr
	case []any:
		out := make([]string, 0, len(arr))
		for _, item := range arr {
			if s, ok := item.(string); ok {
				out = append(out, s)
			}
		}
		return out
	default:
		return nil
	}
}
